28	//   - B1（执行中）：feed-1 登记 M1 1.000 克（序号 1，结果显示为 1），
29	//     feed-2 登记 M1 3 克（序号 2，另一登记人）；
30	//   - B2（执行中）：feed-b2 登记 M1 5 克（序号 1，与 B1 各自编号）。
31	//
32	// 返回落盘后的台账文件内容，供各用例改坏后重写。
33	func setupFeedingRequestLedger(t *testing.T, dir string) []byte {
34		t.Helper()
35		s, err := Open(dir)
36		if err != nil {
37			t.Fatalf("Open 失败: %v", err)
38		}
39		registerStandardRecipe(t, s, "recipe-1") // M1=100、M2=0.5、M3=0.010
40		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
41			t.Fatal(err)
42		}
43		if _, err := s.StartBatch("s1", "B1"); err != nil {
44			t.Fatal(err)
45		}
46		if _, err := s.CreateBatch("b2", "B2", "R1", "v1", 5); err != nil {
47			t.Fatal(err)
48		}
49		if _, err := s.StartBatch("s2", "B2"); err != nil {
50			t.Fatal(err)
51		}
52		t1 := feedingRequestBaseTime()
53		if _, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", t1, "张三"); err != nil {
54			t.Fatal(err)
55		}
56		if _, err := s.AddFeeding("feed-2", "B1", "M1", "3", t1.Add(2*time.Hour), "王五"); err != nil {
57			t.Fatal(err)
58		}
59		if _, err := s.AddFeeding("feed-b2", "B2", "M1", "5", t1.Add(time.Hour), "李四"); err != nil {
60			t.Fatal(err)
61		}
62		if err := s.Close(); err != nil {
63			t.Fatal(err)
64		}
65		good, err := os.ReadFile(filepath.Join(dir, stateFileName))
66		if err != nil {
67			t.Fatal(err)
68		}
69		return good
70	}
71	
72	// corruptFeedingRequestResult 把正常台账内容中 feed-1 请求的保存结果替换为
73	// mutate 给出的值（mutate 返回 nil 表示删除该字段），返回改写后的文件内容。
74	func corruptFeedingRequestResult(t *testing.T, good []byte, mutate func() json.RawMessage) []byte {
75		t.Helper()
76		var st persistedState
77		if err := json.Unmarshal(good, &st); err != nil {
78			t.Fatal(err)
79		}
80		req := st.Requests["feed-1"]
81		if req == nil {
82			t.Fatalf("正常台账中应存在 feed-1 请求记录")
83		}
84		req.Result = mutate()
85		data, err := json.MarshalIndent(&st, "", "  ")
86		if err != nil {
87			t.Fatal(err)
88		}
89		return data
90	}
91	
92	// marshalFeedingView 把一条投料视图序列化为保存结果使用的 JSON。
93	func marshalFeedingView(t *testing.T, v FeedingView) json.RawMessage {
94		t.Helper()
95		raw, err := json.Marshal(v)
96		if err != nil {
97			t.Fatal(err)
98		}
99		return raw
100	}
101	
102	// 已保存的成功投料请求的结果缺失、为 null、为空对象，或被替换成另一条投料、
103	// 指向批次中不存在的序号、内容（物料、克数、时间、登记人）与实际投料或原
104	// 提交内容不符时，Open 必须返回 ErrCorruptData：错误信息指出问题请求编号
105	// 及关联批次，不返回可用的台账对象，也不改写原文件。
106	func TestOpenRejectsCorruptFeedingRequestResult(t *testing.T) {
107		t1 := feedingRequestBaseTime()
108		cases := []struct {
109			name   string
110			mutate func() json.RawMessage
111		}{
112			{"结果缺失", func() json.RawMessage { return nil }},
113			{"结果为 null", func() json.RawMessage { return json.RawMessage("null") }},
114			{"结果为空对象", func() json.RawMessage { return json.RawMessage(`{}`) }},
115			{"结果不是投料记录对象", func() json.RawMessage { return json.RawMessage(`"not-an-object"`) }},
116			{"结果被替换成同批次另一条投料", func() json.RawMessage {
117				// B1 序号 2 的记录真实存在，但它属于 feed-2，不是 feed-1 的登记。
118				return marshalFeedingView(t, FeedingView{Seq: 2, MaterialNo: "M1", Grams: "3", Time: t1.Add(2 * time.Hour), Registrar: "王五"})
119			}},
120			{"结果指向批次中不存在的序号", func() json.RawMessage {
121				return marshalFeedingView(t, FeedingView{Seq: 9, MaterialNo: "M1", Grams: "1", Time: t1, Registrar: "张三"})
122			}},
123			{"结果物料与实际投料不符", func() json.RawMessage {
124				return marshalFeedingView(t, FeedingView{Seq: 1, MaterialNo: "M2", Grams: "1", Time: t1, Registrar: "张三"})
125			}},
126			{"结果克数与实际投料不符", func() json.RawMessage {
127				return marshalFeedingView(t, FeedingView{Seq: 1, MaterialNo: "M1", Grams: "2", Time: t1, Registrar: "张三"})
128			}},
129			{"结果时间与实际投料不符", func() json.RawMessage {
130				return marshalFeedingView(t, FeedingView{Seq: 1, MaterialNo: "M1", Grams: "1", Time: t1.Add(time.Minute), Registrar: "张三"})
131			}},
132			{"结果登记人与实际投料不符", func() json.RawMessage {
133				return marshalFeedingView(t, FeedingView{Seq: 1, MaterialNo: "M1", Grams: "1", Time: t1, Registrar: "李四"})
134			}},
135			{"结果被替换成其他批次的同序号投料", func() json.RawMessage {
136				// B2 的序号 1 与 B1 各自编号；B2 的记录不能作为 feed-1 的对应投料。
137				return marshalFeedingView(t, FeedingView{Seq: 1, MaterialNo: "M1", Grams: "5", Time: t1.Add(time.Hour), Registrar: "李四"})
138			}},
139		}
140		for _, tc := range cases {
141			t.Run(tc.name, func(t *testing.T) {
142				dir := t.TempDir()
143				good := setupFeedingRequestLedger(t, dir)
144				bad := corruptFeedingRequestResult(t, good, tc.mutate)
145				if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
146					t.Fatal(err)
147				}
148	
149				s, err := Open(dir)
150				if !errors.Is(err, ErrCorruptData) {
151					t.Fatalf("保存结果损坏应返回 ErrCorruptData，得到 %v", err)
152				}
153				if s != nil {
154					s.Close()
155					t.Fatalf("损坏台账不应返回可用的 Store 对象")
156				}
157				msg := err.Error()
158				for _, want := range []string{"feed-1", "B1"} {
159					if !strings.Contains(msg, want) {
160						t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
161					}
162				}
163				got, err := os.ReadFile(filepath.Join(dir, stateFileName))
164				if err != nil {
165					t.Fatal(err)
166				}
167				if !bytes.Equal(got, bad) {
168					t.Fatalf("拒绝打开不应改动台账文件")
169				}
170			})
171		}
172	}
173	
174	// 原请求对应的批次不存在时，保存的结果不能单独作为登记成功的依据：
175	// 即使结果本身内容完整、与其他批次的某条投料完全吻合，也按损坏处理。
176	func TestOpenRejectsFeedingRequestResultWhenBatchMissing(t *testing.T) {
177		dir := t.TempDir()
178		good := setupFeedingRequestLedger(t, dir)
179		var st persistedState
180		if err := json.Unmarshal(good, &st); err != nil {
181			t.Fatal(err)
182		}
183		// 删除 B1（feed-1、feed-2 对应的批次），保留完整的 B2 及其请求。
184		kept := st.Batches[:0]
185		for _, b := range st.Batches {
186			if b.BatchNo != "B1" {
187				kept = append(kept, b)
188			}
189		}
190		st.Batches = kept
191		bad, err := json.MarshalIndent(&st, "", "  ")
192		if err != nil {
193			t.Fatal(err)
194		}
195		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
196			t.Fatal(err)
197		}
198	
199		s, err := Open(dir)
200		if !errors.Is(err, ErrCorruptData) {
201			t.Fatalf("原批次不存在但保留请求结果应返回 ErrCorruptData，得到 %v", err)
202		}
203		if s != nil {
204			s.Close()
205			t.Fatalf("损坏台账不应返回可用的 Store 对象")
206		}
207		if !strings.Contains(err.Error(), "B1") {
208			t.Fatalf("错误信息应指出关联批次 B1，得到 %v", err)
209		}
210		got, err := os.ReadFile(filepath.Join(dir, stateFileName))
211		if err != nil {
212			t.Fatal(err)
213		}
214		if !bytes.Equal(got, bad) {
215			t.Fatalf("拒绝打开不应改动台账文件")
216		}
217	}
218	
219	// 正常写法差异不能误判为损坏：原请求填写 1.000、保存结果显示 1 是同一次
220	// 登记；保存结果的投料时间与实际记录表示同一时刻、仅时区写法不同也合法。
221	// 台账应正常打开，重放仍返回第一次成功登记的结果，批次查询显示实际投料。
222	func TestOpenAcceptsFeedingRequestResultFormatVariants(t *testing.T) {
223		dir := t.TempDir()
224		good := setupFeedingRequestLedger(t, dir)
225		t1 := feedingRequestBaseTime()
226	
227		// 把 feed-1 保存结果的时间改成同一时刻的另一种时区写法（克数保持
228		// 系统写入的 “1”，与原提交的 “1.000” 本就写法不同）。
229		var st persistedState
230		if err := json.Unmarshal(good, &st); err != nil {
231			t.Fatal(err)
232		}
233		var result FeedingView
234		if err := json.Unmarshal(st.Requests["feed-1"].Result, &result); err != nil {
235			t.Fatal(err)
236		}
237		if result.Grams != "1" {
238			t.Fatalf("系统保存的结果克数应为 1（原提交 1.000），得到 %q", result.Grams)
239		}
240		result.Time = t1.In(time.FixedZone("UTC+8", 8*3600))
241		st.Requests["feed-1"].Result = marshalFeedingView(t, result)
242		data, err := json.MarshalIndent(&st, "", "  ")
243		if err != nil {
244			t.Fatal(err)
245		}
246		if err := os.WriteFile(filepath.Join(dir, stateFileName), data, 0o644); err != nil {
247			t.Fatal(err)
248		}
249	
250		s, err := Open(dir)
251		if err != nil {
252			t.Fatalf("写法差异不应判为损坏: %v", err)
253		}
254		defer s.Close()
255	
256		// 重放取回第一次成功登记的那条投料：序号 1、M1、显示 1 克、
257		// 时间与原投料为同一时刻、登记人张三。
258		replay, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", t1, "张三")
259		if err != nil {
260			t.Fatalf("重放应成功: %v", err)
261		}
262		checkFeedingView(t, replay, 1, "M1", "1", t1, "张三")
263	
264		// 批次查询仍显示实际投料，重放没有追加记录。
265		view, err := s.GetBatch("B1")
266		if err != nil {
267			t.Fatal(err)
268		}
269		if len(view.Feedings) != 2 {
270			t.Fatalf("B1 应仍为 2 条投料，得到 %d 条", len(view.Feedings))
271		}
272		checkFeedingView(t, &view.Feedings[0], 1, "M1", "1", t1, "张三")
273		checkFeedingView(t, &view.Feedings[1], 2, "M1", "3", t1.Add(2*time.Hour), "王五")
274	}
275	
276	// 台账正常打开后，保存内容中的投料请求结果被改坏：下一次查询或写入必须
277	// 返回 ErrCorruptData——即使本次访问的是另一条正常记录或另一个正常批次，
278	// 也不能忽略损坏的投料请求；被拒绝的重放不得返回损坏的保存结果，被拒绝
279	// 的写入不留业务变化、不占用请求编号，原台账内容不变。恢复后原成功请求
280	// 仍可幂等重放，被拒绝过的请求编号可以正常使用。
281	func TestFeedingRequestResultCorruptionAfterOpenDetectedOnNextAccess(t *testing.T) {
282		dir := t.TempDir()
283		good := setupFeedingRequestLedger(t, dir)
284		t1 := feedingRequestBaseTime()
285	
286		s, err := Open(dir)
287		if err != nil {
288			t.Fatal(err)
289		}
290		defer s.Close()
291	
292		// 打开后把 feed-1 的保存结果改坏为空对象（其余记录保持完整）。
293		bad := corruptFeedingRequestResult(t, good, func() json.RawMessage {
294			return json.RawMessage(`{}`)
295		})
296		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
297			t.Fatal(err)
298		}
299	
300		// 查询损坏批次与正常批次都必须失败，不能沿用此前读到的内容。
301		for _, batchNo := range []string{"B1", "B2"} {
302			if v, err := s.GetBatch(batchNo); !errors.Is(err, ErrCorruptData) {
303				t.Fatalf("查询批次 %q 应返回 ErrCorruptData，得到 %v", batchNo, err)
304			} else if v != nil {
305				t.Fatalf("被拒绝的查询不应返回部分台账视图: %+v", v)
306			}
307		}
308		// 用原编号、原内容重放损坏的请求：不得把损坏的保存结果当成成功结果
309		// 返回，必须报损坏。
310		if _, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", t1, "张三"); !errors.Is(err, ErrCorruptData) {
311			t.Fatalf("重放损坏的投料请求应返回 ErrCorruptData，得到 %v", err)
312		}
313		// 对正常批次的新写入同样不能绕过。
314		if _, err := s.AddFeeding("feed-new", "B2", "M1", "1", t1, "赵六"); !errors.Is(err, ErrCorruptData) {
315			t.Fatalf("损坏台账上写入正常批次应返回 ErrCorruptData，得到 %v", err)
316		}
317	
318		// 被拒绝的访问不改动文件、不占用请求编号。
319		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
320		if err != nil {
321			t.Fatal(err)
322		}
323		if !bytes.Equal(after, bad) {
324			t.Fatalf("被拒绝的访问不应改动台账文件")
325		}
326		if bytes.Contains(after, []byte("feed-new")) {
327			t.Fatalf("被拒绝的写入不应留下请求记录")
328		}
329	
330		// 恢复后：原成功请求仍取回第一次登记的结果，批次投料保持原样，
331		// 被拒绝过的请求编号可以正常使用并取得连续序号。
332		if err := os.WriteFile(filepath.Join(dir, stateFileName), good, 0o644); err != nil {
333			t.Fatal(err)
334		}
335		replay, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", t1, "张三")
336		if err != nil {
337			t.Fatalf("恢复后重放原成功请求失败: %v", err)
338		}
339		checkFeedingView(t, replay, 1, "M1", "1", t1, "张三")
340		view, err := s.GetBatch("B1")
341		if err != nil {
342			t.Fatal(err)
343		}
344		if len(view.Feedings) != 2 {
345			t.Fatalf("B1 应仍为 2 条投料，得到 %d 条", len(view.Feedings))
346		}
347		f, err := s.AddFeeding("feed-new", "B2", "M1", "1", t1, "赵六")
348		if err != nil {
349			t.Fatalf("被拒绝过的请求编号应仍可合法提交: %v", err)
350		}
351		if f.Seq != 2 || f.Grams != "1" {
352			t.Fatalf("新投料结果不正确: %+v", f)
353		}
354	}
355	
356	// 读取核对规则不改变请求内容匹配：正常台账中，用同一编号把原来的 1.000
357	// 改成数值相等的 1 再提交，仍返回 ErrRequestConflict；原内容重放仍取回
358	// 第一次的结果，批次中始终只有真正登记的投料。
359	func TestFeedingRequestResultCheckKeepsPayloadMatching(t *testing.T) {
360		dir := t.TempDir()
361		setupFeedingRequestLedger(t, dir)
362		t1 := feedingRequestBaseTime()
363	
364		s, err := Open(dir)
365		if err != nil {
366			t.Fatal(err)
367		}
368		defer s.Close()
369	
370		if _, err := s.AddFeeding("feed-1", "B1", "M1", "1", t1, "张三"); !errors.Is(err, ErrRequestConflict) {
371			t.Fatalf("1.000 改成数值相等的 1 应返回 ErrRequestConflict，得到 %v", err)
372		}
373		replay, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", t1, "张三")
374		if err != nil {
375			t.Fatalf("原内容重放应成功: %v", err)
376		}
377		checkFeedingView(t, replay, 1, "M1", "1", t1, "张三")
378		view, err := s.GetBatch("B1")
379		if err != nil {
380			t.Fatal(err)
381		}
382		if len(view.Feedings) != 2 {
383			t.Fatalf("冲突不应追加投料，B1 应仍为 2 条，得到 %d 条", len(view.Feedings))
384		}
385	}
