	// 的零实投与负差额是合法内容，按精确克数核对即可，不会误报。
	required, err := planRequirements(r, b.PlannedPortions)
	if err != nil {
		return fmt.Errorf("%w: 关闭请求 %q 对应的批次 %q 的%v",
			ErrCorruptData, reqNo, batchNo, err)
	}
